  str_loading_e_h_name105 = "Sebuah kawasan ngarai yang belum dikembangkan di Denuo Valley Resort.",
  str_loading_e_h_name106 = "Sebuah ruang bawah tanah di hotel, yang berisi peralatan ventilasi dan langkah-langkah peredam suara.",
  str_loading_e_h_name107 = "Sebuah tempat di dalam Federasi Illumina untuk hukuman dan penahanan para penjahat.",
  str_loading_e_h_name108 = "Kawasan hunian dan zona pemerintahan pusat dari Garnisun Lumopolis, yang ditempatkan di Twilight.",
  str_loading_e_h_name109 = "Lumpur yang diciptakan oleh Eclipsite Mudbundle.",
  str_loading_e_h_name110 = "Anomali ruang misterius yang dihasilkan oleh Eclipsium.",
  str_loading_e_h_name111 = "Kawasan hunian dan zona pemerintahan pusat dari Garnisun Lumopolis, yang ditempatkan di Twilight.",
  str_loading_e_h_name112 = "Sebuah ruang tertutup di dalam Penjara Illumina tempat para tahanan disimpan.",
  str_loading_e_h_name113 = "Sebuah dunia rahasia di mana Victoria mendengarkan \"Kebenaran.\"",
  str_loading_e_h_name10004 = "Komunitas Nyaman",
  str_loading_e_h_name10005 = "Lingkungan Ramai",
  str_loading_e_h_name10006 = "Dunia Luar yang Menakutkan",
  str_loading_e_h_name10007 = "Apakah kamu siap, Eve?",
  str_loading_e_h_name20011 = "Di mana keadilan menang.",
  str_loading_e_h_name20012 = "Tempat lahir tulang punggung masa depan Lumopolis.",
  str_loading_e_h_name20013 = "Sebuah enklave mewah para bangsawan.",
  str_loading_e_h_name20014 = "Di mana hiruk-pikuk dan bahaya hidup berdampingan.",
  str_loading_e_h_name20015 = "Siap untuk memulai uji coba berikutnya?",
  str_loading_e_h_name80030001 = "Tempat Tinggal",
  str_loading_e_h_name80030002 = "Jalan-jalan yang Pernah Dikenal Sebelumnya",
  str_loading_e_h_name80030003 = "Tempat untuk Kembali",
  str_loading_e_h_name80030004 = "Dunia Aqua",
  str_loading_e_h_name80040001 = "Jalan Perdagangan Benua Ganda",
  str_loading_e_h_name80040002 = "Longzhou Kecil",
  str_loading_e_h_name80040003 = "Pelabuhan Perdagangan Dwibenua",
  str_loading_e_h_name80040004 = "Legenda Pendekar Pedang Teluk Twin Pavilions",
  str_loading_e_h_name80050001 = "Epik Pahlawan Sipil",
  str_loading_e_h_name80050002 = "Peradaban Berusia Ribuan Tahun",
  str_loading_e_h_name80050003 = "Keyakinan Beribu Tahun",
  str_loading_e_h_name80050004 = "Persaingan Tua Berusia Milenium",
  str_loading_desc1 = "Di bawah Lumopolis, negeri yang diselimuti bayangan, banyak sekali orang yang hidup dengan berdagang dan bertukar informasi membangun kota-kota besar, sementara berbagai pasukan bawah tanah menjadi penguasa yang sebenarnya di tempat-tempat itu.",
  str_loading_desc2 = "Daerah yang dikenal sebagai Astra adalah mutiara dalam lingkaran senja, dan bagi banyak Aurorian, ini adalah satu-satunya tempat yang dikenal sebagai rumah, di mana siang dan malam berganti secara teratur sehingga kehidupan dapat berkembang.",
  str_loading_desc3 = "Berada di kawasan utara yang dingin, orang dapat hidup di sini dengan damai, berkat hebatnya kekuatan magis yang menjaga area kecil ini. Hal-hal penting diputuskan oleh Queen Bethlehem.",
  str_loading_desc4 = "Darkover Crisis terakhir dimulai tujuh belas tahun lalu dan diredakan oleh sebuah aliansi yang terdiri dari banyak faksi. Namun, bahkan dalam komunitas yang terjalin erat, terjadi pertengkaran dan permusuhan. Khususnya jika itu orang Aurorian...",
  str_loading_desc5 = "Satu-satunya habitat Eclipsite yang diketahui. Konon tempat ini memiliki hubungan dengan berbagai fragmen yang ditinggalkan peradaban purba. Kita hanya bisa berspekulasi bahwa mungkin para Eclipsite memilih mendiami tempat ini berdasarkan insting, atau mungkin berdasarkan arahan organisasi misterius, Eclipse...",
  str_loading_desc6 = "Tempat ini adalah sebuah ngarai tanpa cahaya dengan arsitektur yang aneh dan berbahaya, tetapi di sinilah hasil karya peradaban purba yang luar biasa selalu dapat ditemukan. Banyak petualang datang ke tempat ini seperti ngengat mendekati api untuk mencari relik dan trofi dari era yang tidak diketahui, tetapi mereka malah terkubur di sini...",
  str_loading_desc7 = "Setelah Darkover Crisis, yaitu saat pasukan Eclipsite mengerahkan serangan dahsyat 17 tahun lalu, segelintir Caelestite berhasil kabur dari Eraveil. Soroz juga membawa seorang Caelestite dan bersembunyi di bawah tanah, terisolasi dari dunia.",
  str_loading_desc8 = "Bertahun-tahun lalu, saat para Eclipsite membabi buta, kota bawah tanah di kedalaman ribuan meter ini menyelamatkan nyawa yang tak terhitung jumlahnya. Orang-orang di Gannon City bekerja efisien dan mengembangkan teknologi Lumina yang unik untuk membangun sistem pertahanan yang berpusat di Gannon City.",
  str_loading_desc9 = "Aurorian, Eclipsite, Illumina, Lumopolis... Terlalu banyak informasi di kepalamu. Apakah berkumpulnya kembali pasukan Eclipsite berkaitan dengan Darkover Crisis yang terjadi tujuh belas tahun lalu? Perjalanan mencari kebenaran ditakdirkan untuk penuh dengan keberhasilan dan kegagalan...",
  str_loading_desc10 = "Sebuah aliansi nomaden yang susah diatur dan banyak omong, hasil bentukan para pengelana nomaden. Badan anggota-anggotanya kuat tapi bau angin dan jalanan. Mereka berkelana di sekitar Rediesel Desert, menjalani hidup yang bebas dan tanpa kekangan.",
  str_loading_desc11 = "Diyakini sebagai organisasi yang dibentuk oleh Darkover Crisis; yang motif sejatinya tidak diketahui siapa pun. Anggotanya adalah Eclipsite Level Tinggi dan telah merekrut banyak pemberontak dari ras lain demi tujuan yang entah apa. Eclipse menghilang tanpa jejak setelah pasukan koalisi negara kota di daerah Astra berhasil mengatasi Darkover Crisis...",
  str_loading_desc12 = "Dibangun di atas pulau mengambang yang disebut \"Azurite\", kota ini adalah benteng paling aman di dunia. Saat ini, mereka memiliki hierarki kekuasaan yang tersendiri, dipimpin oleh triumvirat Governor, Elder Council dari kelompok Noble, dan Priests dari kelompok Temple. Para bangsawan Lumopolis selalu menjaga tatanan yang ada, sementara kelompok Temple mengajak orang untuk menyembah matahari.",
  str_loading_desc13 = "Federasi yang longgar dengan banyak sekali permukiman di seputar kota bawah tanah Gannon yang luas di garis depan pertempuran melawan pasukan Eclipsite. Illumina Federation telah mengadopsi sistem kepemimpinan kolektif, membentuk masyarakat yang sangat berbeda daripada masyarakat Lumopolis.",
  str_loading_desc14 = "Colossus, sebuah warisan peradaban purba. Ia punya begitu banyak rahasia sampai-sampai konon tidak mungkin menganalisis strukturnya dan memahami prinsip-prinsip di baliknya, bahkan dengan ilmu pengetahuan mutakhir dan usaha semua sarjana sekalipun. Banyak di antaranya bahkan tidak bisa dijelajahi langsung; hanya bangsa Caelestite yang bisa terhubung dengan kecerdasan Colossus melalui kemampuan supranatural untuk menjalin kendali pada level yang dalam dan mengoperasikannya dari sana.",
  str_loading_desc15 = "Kekacauan yang disebabkan Darkover Crisis 17 tahun lalu mengakibatkan hilangnya beberapa benda misterius milik bangsa Caelestite. Tidak ada yang tahu keberadaannya. Bahkan tujuan sejatinya telah sengaja disembunyikan...",
  str_loading_desc16 = "Shadowlord, atau Istvan, adalah sosok yang paling ditakuti di Umbraton. Konon, koleksi di museum pribadinya, Whispering Corridor, berisi banyak sekali benda yang mengerikan. Kalau kamu cukup beruntung selamat dari bahaya di balik batu bata dan sarang laba-laba di sana, kamu mungkin akan menemukan hal-hal yang menarik...",
  str_loading_desc17 = "Penduduk Umbraton tampaknya memiliki dua sisi: murah senyum dan dingin, baik hati dan kasar. Seperti ini jugalah Umbraton. Selama kamu bisa beradaptasi, tempat ini adalah surga. Kalau tidak, neraka.",
  str_loading_desc18 = "Di kontinen Astra, jejak dari banyak relik dari zaman purba telah terkuak, dan Spire yang baru saja ditemukan adalah salah satunya. Yang membuat orang kagum tidak hanya ketinggiannya, tetapi juga kekuatannya yang hebat, dan legenda tentang harta karun yang tersembunyi di dalamnya...",
  str_loading_desc19 = "Penduduk utama kontinen ini adalah orang-orang yang mendapatkan kekuatan dari Cahaya dan bertempur menggunakannya. Selain mereka, tidak banyak kelompok yang bisa melawan Eclipsite secara langsung.",
  str_loading_desc20 = "Makhluk dengan asal usul yang tidak diketahui. Mereka telah menjadi musuh bebuyutan semua masyarakat sejak pertama kali sejarah dituliskan. Kecuali Aurorian, hampir tidak ada yang bisa melawan mereka.",
  str_loading_desc21 = "Material untuk membuat sinyal permintaan bantuan. Bisa digunakan untuk merekrut Aurorian agar bergabung dalam petualangan. Sayangnya, tidak ada jaminan tentang siapa yang akan menanggapi sinyal itu.",
  str_loading_desc22 = "Wujudnya seperti piano, dan dioperasikan dengan memainkannya di panel kontrol Colossus ini. Hanya Caelestite yang bisa memahami bahasanya dengan baik.",
  str_loading_desc23 = [[
Rintangan alami dan banyak Colossus telah menciptakan kedamaian di tempat ini selama ratusan tahun.
Seperti teknologi Colossus, asal mula Caelestite diselubungi misteri dan tidak mungkin dipastikan.
Kalau kedamaian ini bisa bertahan selamanya, tempat ini akan sekali lagi berkembang seperti sebelumnya.]],
  str_loading_desc24 = [[
Waktu belum menyembuhkan luka dari tujuh belas tahun lalu. Yang terjadi pada hari itu terus menyusupi realitas saat ini.
Sejak hari itu, tidak seorang pun kembali ke tempat ini... hingga hari ini.]],
  str_loading_desc25 = [[
Hari itu bersamaan dengan sebuah festival besar, dan orang-orang sedang tidak siap.
Kejatuhan Eraveil seperti tidak terhindarkan, dan Schummer hanyalah pemicu yang memulainya.]],
  str_loading_desc26 = [[
Aviduz dulu sebuah unit spesial di antara banyak Colossus di Eraveil.
Ukurannya besar dan fungsinya tak tertandingi, ia memiliki potensi yang tidak terbatas.
Karena itu, tuntutan yang diberikan pada Navigatornya juga sangat ketat.]],
  str_loading_desc27 = [[
Di inti Aviduz, terdapat sebuah pod pemulih yang dapat digunakan untuk perawatan darurat bagi orang yang terluka parah.
Di bawah perlindungan suatu kekuatan misterius, Schummer memperoleh kekuatan jauh lebih besar daripada yang diperkirakan siapa pun.]],
  str_loading_desc28 = "Area gelap berselimut Darkflow yang berada di batas Land of Eternal Night, tempat siang hari berlalu singkat dan malam hari berlangsung panjang.\nDahulunya merupakan permukiman padat Aurorian sebelum ditinggalkan bertahun-tahun lalu. Puing-puingnya berada di ambang keruntuhan. Kejayaan dan kemakmuran masa lalu lenyap tertutup debu tebal.\nSekarang, tempat ini menjelma menjadi antah berantah luas yang dipenuhi rongsokan reruntuhan, habitat bagi kawanan Eclipsite. Tak akan ada Aurorian yang mau menginjakkan kakinya akibat perasaan tak nyaman yang ditimbulkan oleh Darkflow…",
  str_loading_desc29 = [[
Undercity yang dibangun oleh Illumina Federation di tepi Land of Eternal Night sebagai pangkalan terdepan yang menahan serangan Eclipsite.
Namun, kota ini ditinggalkan selama invasi Eclipsite bertahun-tahun lalu.
Rumor mengatakan bahwa terdapat sejumlah sumber daya dan peralatan yang tertinggal saat pasukan Illumina mundur. Akan tetapi, tak akan ada seorang pun yang sudi kembali karena dia akan disambut oleh Darkflow yang pekat dan kawanan Eclipsite yang tak terhitung jumlahnya.]],
  str_loading_desc30 = [[
Tak banyak orang yang tahu akan terowongan darurat tua ini. Untungnya, terowongan ini masih berdiri kokoh di tengah reruntuhan Undercity.
Kemungkinan, terowongan ini hanyalah satu-satunya jalan menuju permukaan. Jadi, teruskan perjalananmu.
Kalahkan musuh yang menghalangi jalanmu. Susuri terowongan yang tertutup debu dan penuh lubang bekas tembakan ini dengan harapan dan keyakinan untuk bertahan hidup lalu hadapi pertarungan akhir yang tak terhindarkan.]],
  str_loading_h_desc1 = [[
Inilah Rediesel Desert di Southern Astra, tempat padang pasir keemasan membentang sejauh mata memandang.
Di bawah sengatan matahari, tanah yang gersang dan kering kerontang ini merupakan salah satu tempat yang paling tidak dapat ditinggali di Astra.
Hanya makhluk yang paling keras kepala dan tangguh yang dapat hidup bebas di sini.]],
  str_loading_h_desc2 = [[
Orang hanya dapat menjangkau mata badai Red-Eye Gorge dengan melalui angin yang berembus kuat dan hujan yang luar biasa lebat.
Abu vulkanik yang dulu menyelimuti tanah ini sekarang menjadi pupuk, mengisi bentangan yang hijau ini dengan kehidupan.
Rasanya hampir seolah-olah tragedi di masa lampau itu tidak pernah terjadi...]],
  str_loading_h_desc3 = [[
Suasana laboratorium bawah tanah yang terbuat dari beton ini memang murung dan membosankan.
Peralatan operasi berserakan di meja kerja, dengan kontur yang dingin tanpa jiwa, memantulkan sorot cahaya yang terasa mengancam.
Namun, hanya dari tempat seperti itulah bunga-bunga paling indah bermekaran.]],
  str_loading_h_desc4 = [[
Di dalam ingatan Eve, langit di kampung halamannya berwarna biru terang tanpa awan.
Kalau saja keadaan tidak berubah tiba-tiba, mungkin perasaan bahagia yang sementara itu bisa bertahan selamanya.
Andai saja...]],
  str_loading_h_desc5 = [[
Di sebuah oasis di kedalaman Rediesel Desert, terdapat suatu jalan yang dibangun oleh Rediesel Wrench.
Walau jalan itu tampak tidak terawat, setiap batu bata yang rusak di sana berisi cinta.
Bentangan tanah yang bersahaja ini adalah tempat paling hangat di dunia.]],
  str_loading_h_desc6 = [[
Tir' Hotel adalah tujuan wisata utama bagi bangsawan Lumopolis.
Di sanalah tempat terbaik untuk menikmati pemandangan indah Celestial Coast!
Reservasi saat ini dapat dibuat dengan diskon berbatas waktu.]],
  str_loading_h_desc7 = [[
Ocean Sovereign adalah upacara pengorbanan yang awalnya dilakukan Aurorian yang dulu meninggali pesisir ini.
Para peserta harus menjalani berbagai ujian dan menyelesaikan tantangan sulit.
Diyakini bahwa kemenangan mereka akan membawa berkat berupa cuaca yang baik dan ikan yang melimpah.]],
  str_loading_h_desc8 = [[
Menurut legenda kuno, terdapat sebuah puri yang muncul dari bawah laut.
Untuk menyelamatkan warganya, seorang raja menerima ujian dari para dewi.
Waktu telah berlalu, krisis itu telah lewat, tetapi Raja itu belum kembali.]],
  str_loading_h_desc9 = [[
Tidak jelas siapa yang menginginkan penciptaan domain ini, tetapi tempat itu adalah suatu ruang hampa yang berisi penampakan aneh.
Di dalamnya, terdapat mereka yang secara membabi buta mencari kekuatan kesatria yang hilang, dan mereka yang mendambakan kesempatan untuk terbebas dari perbudakan.
Terima kutukanmu dan robohkan dindingnya.]],
  str_loading_h_desc10 = [[
Menghadapi kekalahan, Caroline mengutuk setiap orang dengan kekuatan terakhirnya.
Dan Raja yang ingin dia bangkitkan mungkin telah mendengar permintaannya...]],
  str_loading_h_desc11 = [[
Saatnya para Scrounger beraksi lagi.
Para pencuri licik ini muncul dari kegelapan hanya untuk kembali ke bayangan itu secepat mereka muncul.]],
  str_loading_h_desc12 = "Sebuah menara penjaga Illumina Undercity berdiri di gurun yang tandus. Menara yang sudah ada di sini sejak Illumina mendirikan Undercity dan garis pertahanannya inilah yang menyaksikan perjuangan tak kenal lelah dari tentara Illumina yang pantang menyerah.",
  str_loading_h_desc13 = "Ini adalah medan tempur di perbatasan Undercity. Konon, benteng yang telah didirikan para prajurit Illumina di sini mampu menghentikan sebagian besar serangan Eclipsite.",
  str_loading_h_desc14 = "Pangkalan transportasi ini berdiri di gerbang Undercity 24. Di sinilah barang yang masuk dan keluar kota ditangani. Meskipun tak seorang pun bekerja di sini sekarang, kehidupan yang aktif dan teratur dari orang-orang di sini bisa dilihat dari menara pengangkat, kendaraan pengangkut, dan beragam barangnya.",
  str_loading_h_desc15 = "Illumina Undercity yang terbengkalai dan hancur karena kebakaran besar. Penduduk yang dulu menghuni tempat ini sudah dievakuasi, dan para prajurit yang tinggal di sini sekarang bertempur di garis depan. Setiap mantan penduduk bertempur di medan perang masing-masing dan bertekad untuk kembali ke rumah mereka lagi kelak.",
  str_loading_h_desc16 = "Di Illumina, bahkan lorong-lorongnya sekalipun bersinar dengan jernih dan berkilau dengan cahaya baja. Saat melihatnya untuk pertama kalinya, mau tak mau orang pasti akan mengomentari betapa terangnya lorong itu.",
  str_loading_h_desc17 = [[
Bangsa Caelestite mempraktekkan segala macam kebiasaan yang menarik selama festival ini dan mendekorasi rumah mereka.
Mereka percaya bahwa ini adalah cara untuk berhubungan dengan alam dan dengan nenek moyang mereka.]],
  str_loading_h_desc18 = [[
Sejarah itu seperti bulu yang terperangkap di bawah cangkang yang berat.
Jalan menuju masa depan tergantung pada bagaimana kita menavigasi jalan di depan.]],
  str_loading_h_desc19 = "Perdagangan bebas di pasar bebas—apa saja bisa diperdagangkan di Umbraton.\nGuild adalah perwujudan dari perdagangan dan modal yang membawa vitalitas tak terbatas untuk Umbraton.",
  str_loading_h_desc20 = "Geng bawah tanah Umbraton dikenal sebagai \"bayangan dalam bayangan\". Beroperasi di wilayah abu-abu, mereka tidak mampu mengekspos diri mereka ke mata publik. Namun, mereka bermimpi menggunakan subversi sembunyi-sembunyi mereka untuk menjadi sukses dalam semalam dan diterima di masyarakat yang lebih luas. Ketika awan gelap terbentuk di atas, mereka mulai menjalankan segala macam operasi rahasia...",
  str_loading_h_desc21 = "Bendungan Bekas Luka berdiri tegak dan bangga melalui bencana alam atau bencana buatan, badai hujan, atau peperangan. Tidak hanya membuktikan kegigihannya kepada pembuatnya, Shadowlord, sekaligus juga membawa rasa aman yang besar bagi orang-orang Umbraton.",
  str_loading_h_desc22 = "Para bangsawan Lumopolis memamerkan kekayaan mereka dengan bangga, meskipun tampilan kemewahan mereka lahir dari kerja keras masyarakat umum. Dan kota yang terletak di bawah Lumopolis adalah tempat tinggal para masyarakat itu. Meskipun ini adalah dunia yang terpisah dari tanah para bangsawan, kehidupan mengalir dengan vitalitas yang hangat dan pasti. Bagaimanapun, ini masih bagian dari Lumopolis. Bahkan dengan status yang lebih rendah, orang-orang jauh lebih baik daripada mereka yang tinggal di luar batas kota.",
  str_loading_h_desc23 = "Sebagai pusat peradaban Aurorian, Lumopolis menganggap dirinya sebagai pemimpin pasukan kontinen. Untuk alasan tersebut, aula ini dibangun untuk menunjukkan kekuatan dan kejayaan Lumopolis kepada para pemimpin asing yang diundang ke kota untuk berpartisipasi dalam pertemuan penting global. Dengan cara ini, Lumopolis mempertahankan keunggulan dalam semua konferensi yang dihadiri oleh berbagai kekuatan dan membuat banyak sekali keputusan yang memengaruhi seluruh kontinen sesuai dengan cita-citanya.",
  str_loading_h_desc24 = "Festival kembang api menyelimuti keseluruhan Azurite. Di bawah pertunjukan yang brilian, orang-orang berkumpul bersama untuk menikmati perayaan besar. Sebagai pusat peradaban di Astra, Lumopolis layak mendapatkan hari spesial itu. Namun, tiada hari yang tak berakhir.",
  str_loading_h_desc25 = "Bagi orang-orang Northland, tanah musim dingin abadi tempat hutan berselimut salju adalah pemandangan yang tak asing lagi. Ketika cahaya fajar mulai menyinari pucuk pohon yang beku ini, sinar mentari membias melalui butiran-butiran esnya, menciptakan konserto mengagumkan dari serbuan cahaya yang kini hadir melambangkan iman orang-orang yang menyebut tanah ini sebagai rumah.",
  str_loading_h_desc26 = "Banyak orang percaya bahwa danau ini diciptakan oleh gletser yang mencair sejak lama, tetapi tidak ada yang bisa menjelaskan mengapa danau yang dalam, tenang, dan seperti cermin ini tetap tidak membeku sepanjang tahun. Inilah sebabnya mengapa banyak orang percaya bahwa munculnya Mirror Lake adalah hadiah dari surga. Dikabarkan bahwa ketika keluarga kerajaan Northland mengunjungi tempat ini, mereka menyaksikan sebuah penglihatan, dan bunga Narcissus yang mekar di sekitar Lake Mirror malah semakin menambah misterinya.",
  str_loading_h_desc27 = "Ada yang mengatakan bahwa fajar pertama yang jatuh di cakrawala Northland adalah yang melindungi tempat ini dan mengusir kepungan kegelapan tanah dari malam yang abadi. Namun, legenda lain percaya bahwa kekuatan sebenarnya dari Northland terletak pada tekad abadi untuk melindungi tanah ini—tekad yang lebih cerah daripada Aurora yang gemerlap dan fajar yang bersinar, selamanya tidak berubah dan mulia selamanya.",
  str_loading_h_desc28 = [[
Reruntuhan yang benar-benar terisolasi dari dunia dan dipenuhi dengan bangunan yang belum pernah terlihat sebelumnya.
Sepertinya tidak ada jejak penduduk asli di sini.]],
  str_loading_h_desc29 = [[
Reruntuhan ini runtuh dengan cepat karena alasan yang tidak diketahui.
Baik mesin yang sibuk memperbaiki reruntuhan dan Eclipsites yang hidup di dalamnya menjadi tidak stabil.]],
  str_loading_h_desc30 = [[
Masih banyak rahasia yang belum terpecahkan di kota ini.
Atau, setiap orang sudah memiliki jawaban di hati mereka...]],
  str_loading_h_desc31 = "Inti energi ini telah berjalan selama bertahun-tahun tanpa batas. Ia berjuang seperti pasien sekarat. Setiap detak jantung bisa jadi yang terakhir.",
  str_loading_h_desc32 = "Pusat data Abby. Modul biologis gila ini terus-menerus memproduksi dan meningkatkan Eclipsite. Jeritan marah dan mengerikan mereka telah menghantui hub.",
  str_loading_h_desc33 = "Sebuah pulau kecil di sebelah timur Astra yang kaya akan sumber daya dan memiliki sedikit Eclipsite. Seabad yang lalu, Koufu-jou dibangun di tengah Cloud Island dan seorang jenderal diutus oleh pulau utama untuk memerintah di sana. Sejak saat itu, kedua pulau itu saling berselisih. Di balik masa lalu yang ditakuti oleh penduduk Cloud Island, jenderal ini akan membawa rahasianya dan Cloud Island ke masa depan yang tak terduga...",
  str_loading_h_desc34 = "Tradisi Kasuga Festival di Cloud Island telah dilestarikan dari generasi ke generasi. Waktu terus berjalan, orang hidup dan mati, tapi bunga sakura akan tetap sama sepanjang masa.",
  str_loading_h_desc35 = "Night Festivities adalah acara spesial di Koufu-jou, yang diadakan untuk mengenang arwah orang yang telah meninggal. Saat bunga sakura bermekaran, orang akan menyelenggarakan Festival Kasuga setiap tahun. Semua orang berdandan, memakai topeng kucing dan membawa lampion sambil berbaris di jalan di malam hari. Mereka percaya bahwa mereka dapat terhubung dengan dunia akhirat dengan cara ini dan bisa melihat orang yang mereka cintai yang telah meninggal untuk satu kali lagi.",
  str_loading_h_desc36 = "Koufu-jou berada di tempat tertinggi di Cloud Island. Ketika orang-orang dari seluruh Cloud Island melihat ke atas, tempat itu tampak seolah-olah terletak di awan, menambah misteri dan kekhidmatannya. Nenek moyang Cloud Island membangun Koufu-jou bata demi bata bertahun-tahun yang lalu, tetapi hari ini, api yang membara menghanguskan semuanya. Saat itulah orang mulai memikirkan apa yang sebenarnya mereka inginkan. Sekarang pertanyaannya, siapa yang menyambut perang, dan berapa banyak yang tewas dalam kobaran api?",
  str_loading_h_desc37 = "Mayat hidup bertransformasi selama waktu Yin berlangsung, lalu menciptakan medan kekuatan yang menghantui Cloud Island, sedangkan artefak suci yang terbentuk selama waktu Yang, memiliki kekuatan murni Yang untuk melenyapkan semua roh jahat. Namun, ketika Yin dan Yang berada di tangan orang yang serakah dan egois, keinginan yang tidak terkendali kemudian berubah menjadi sesuatu yang lebih menakutkan daripada hantu.",
  str_loading_h_desc38 = "Terletak di daerah selatan Rediesel Desert, badai tanpa henti ini menyelimuti area sekitarnya dengan kabut kuning panas sejauh mata memandang, hanya diselingi dengan tulang-belulang putih dan pepohonan layu tanpa satu pun tanaman hijau yang tampak. Namun, masih terdapat tanda-tanda kehidupan di tempat sunyi nan suram ini. Selain Kalajengking Suar dan Ular Cincin Merah yang bersembunyi di bayang-bayang balik batu, predator yang lebih besar lagi berkeliaran di hamparan pasir. Di sini, yang lemah akan dimangsa utuh-utuh.",
  str_loading_h_desc39 = "Tanah di sekitar gunung berapi dibanjiri oleh batu pasir hitam kasar. Jika dilihat dari atas, lava panas mengalir menuruni ceruk gunung, membentuk air terjun lava yang memanjakan mata di tepi jurang. Semakin dekat dengan gunung berapi, semakin panas pula udaranya sehingga bernapas pun sulit. Hal yang lebih menakjubkan adalah kerikil batu pasir yang melayang di udara berkat kekuatan yang luar biasa.",
  str_loading_h_desc40 = "Blazing Tooth Canyon, yang terletak dekat tepi Eternal Night, dinamai demikian karena topografi lanskapnya bergerigi. Sisinya yang curam tampak seakan langsung menghunjam tanah. Sungainya yang sudah lama mengering di bawah teriknya sinar matahari begitu berliku dan retak di sana-sini sehingga tak cocok jika disebut sebagai jalan. Namun, mungkin rintangan yang tampak mustahil dilintasi inilah yang ditetapkan sebagai trek balapan Rediesel Wrench edisi pertama…",
  str_loading_h_desc41 = "Untuk menutup ruangan, blokade gerbang dengan batu bata dan ubin, lalu tuangkan pasir dan lumpur ke celah jendela. Dengan mengubahnya menjadi jalanan atau tembok biasa, tempat ini akan terhapus dari peta selamanya. Sudut dunia ini hilang tanpa diketahui orang, eksklusif hanya untuk True Order. Lumopolis sangatlah luas. Maka dari itu, lubang seperti jalan pintas ini tak akan mudah diketahui.",
  str_loading_h_desc42 = "Berdiri di balik tebalnya tirai sebelum pertunjukan dimulai. Kau harus menahan degub kencang jantungmu karena panggung ini tak mengizinkan siapa pun berhenti begitu tirainya dibuka. Jawaban atas performa yang sempurna hanya tergantung pada upayamu selanjutnya.",
  str_loading_h_desc43 = "Bisa dibilang bahwa boneka hanyalah benda tanpa nyawa dan jiwa. Tapi, saat boneka berpose layaknya makhluk hidup, seseorang bisa mengira boneka itu jauh lebih manusiawi dibanding manusia itu sendiri. Mungkin, dalam benak kita, kita berharap benda seperti itu juga memiliki jiwa.",
  str_loading_h_desc44 = "Kalau ada satu benda yang bisa menggambarkan Eraveil, benda itu pastilah dandelion. Bunga putih mungil yang lembut ini tumbuh menghiasi dataran Eraveil. Angin yang berembus meniup dandelion menciptakan ilusi hujan salju. Tak semua orang menyukai dandelion. Mereka menganggap bahwa dandelion tak memberikan nuansa gembira pada hati karena bunga ini hanya mengekor ke mana pun angin bertiup. Namun, di Eraveil, entah ke arah mana pun angin berembus, kau akan menemukan banyak dandelion beterbangan. Meski hilir mudik terbawa angin, dandelion tak pernah meninggalkan tempat asalnya.",
  str_loading_h_desc45 = "Eraveil memang tempat yang menenangkan. Angin di sini selalu berembus lembut, pemandangannya selalu hijau, dan udaranya selalu menyejukkan. Namun, semuanya terasa hampa setelah sekian lama. Kesepian dapat dirasakan di lubuk hati terdalam, seolah-olah ada sesuatu yang hilang di alam liar ini—tempat ayam jago menyambut fajar dan asap menari-nari saat senja.",
  str_loading_h_desc46 = [[
Mengikuti petunjuk, kamu pulang ke Eraveil, tempat yang penuh kenangan mendalam.
Namun, di bawah Eraveil, terkubur sebuah rahasia.
Rahasia ini menceritakan tentang Eraveil, masa lalu dan masa depan, serta tentang dirimu.]],
  str_loading_h_desc47 = "Tersembunyi di ceruk luas di bawah White Tower, lorong ini adalah jalan masuk menuju bawah tanah!\nMungkin saja, kamu menjadi orang pertama yang membukanya setelah ribuan tahun.\nJelajahi reruntuhan jauh di bawah tanah… Di sana, kamu bisa saja menemukan sesuatu yang selama ini kamu cari.",
  str_loading_h_desc48 = "Perangkat misterius berbentuk cincin yang berada di pusat \"Colossus Maintenance Base\" tepat di bawah Eraveil ini tampaknya adalah pusat kendali yang memungkinkan keseluruhan kompleks yang luas ini tetap aktif hingga saat ini.\nNamun, tampaknya perangkat ini sudah lama tak terawat. Aku pun tak yakin perangkat ini masih berfungsi atau tidak…",
  str_loading_h_desc49 = [[
Asal-usul berdirinya menara putih di Eraveil ini pun juga misteri.
White Tower yang menjulang tinggi ini pun beresonansi dengan teknologi kuno yang masih ada hingga saat ini. Apakah resonansi ini menggambarkan ancaman dari masa lalu, atau malah harapan untuk masa depan?]],
  str_loading_h_desc50 = "Perangkat misterius di markas bawah tanah Eraveil tampaknya memiliki kekuatan untuk mengubah Aurorian. Petunjuk cara kerjanya raib tak bersisa dan tak ada seorang pun yang tahu apa fungsi perangkat ini sebenarnya. Sebelum menggunakannya, seseorang harus memperhitungkan risiko yang mungkin terjadi…",
  str_loading_h_desc51 = [[
Kamu kembali ke sini untuk menggunakan "Chord of the Law."
Meskipun jalan ini mungkin terlalu sulit bagi seorang Caelestite, harapan sekecil apa pun tetap layak untuk diperjuangkan.]],
  str_loading_h_desc52 = "Atmosfir yang harmonis dan pemandangan alam... Bagi Caelestite, tak ada warisan yang lebih baik dari Cloud Gardens. Ada banyak hal yang harus diurus di halaman White Tower yang luas ini. Semua keberadaan yang tak berarti di tanganmu bisa turut andil dalam menentukan masa depan Caelestite.",
  str_loading_h_desc53 = "Fountain of Hope di depan Hyacinth Tower ini merupakan pusat Cloud Gardens. Kamu bisa mengobrol dengan teman, melepaskan ikan yang kamu tangkap di kolam, atau melemparkan Hope Coin ke kolam sambil mengutarakan permintaan.",
  str_loading_h_desc54 = "Ruangan yang paling umum di Cloud Gardens. Dilengkapi pencahayaan yang cukup dan ventilasi yang baik, ruangan ini cocok digunakan sebagai tempat tinggal maupun ruang penyimpanan. Ingat, bersihkan dulu sebelum digunakan, ya.",
  str_loading_h_desc55 = "Di balik selimut yang tertata rapi, ada tumpukan pakaian yang belum dicuci selama seminggu. Lemari yang tertutup rapat itu dipenuhi oleh cangkir-cangkir yang akan jatuh. Crunchy Munchy Crunches yang sudah dimakan separuh, buku, dan majalah berserakan di mana-mana... Apa kamar bocah laki-laki selalu seperti ini?",
  str_loading_h_desc56 = "\"Tak ada keluarga yang abadi, yang abadi hanyalah keuntungan.\" Seperti layaknya keluarga kuno lain di Umbraton, setiap jengkal rumah keluarga Andersen dibangun berkat keuntungan yang berlimpah. Tapi, Count Andersen tampaknya mempunyai preferensi investasi yang berbeda.",
  str_loading_h_desc57 = "Buat tamu keluargamu betah dan tanamkan rasa takut pada musuh keluargamu. Perintah master harus dipatuhi apa pun yang terjadi. Namun, pelayan dan master memiliki kepribadian yang sama—pelayan jempolan keluarga Andersen ini tanpa cela dan tak kenal ampun, bahkan saat ia sedang menguji masternya.",
  str_loading_h_desc58 = [[
Binatang buas yang menakjubkan biasanya ditemukan jauh dari manusia, hidup bebas di pegunungan, hutan, hutan belantara, padang salju, atau laut dalam. Tidak seperti hewan normal, mereka dapat menggunakan Lumina dan memiliki berbagai kemampuan atau karakteristik yang unik. Makhluk ramah ini jarang berinteraksi dengan Aurorian, tetapi mereka sering membantu dalam menghadapi krisis.
Namun, pada saat yang sama, perubahan habitat mereka dan kekurangan reproduksi mereka sendiri telah menyebabkan penurunan populasi mereka secara keseluruhan, dan banyak binatang yang menakjubkan sekarang terancam punah.]],
  str_loading_h_desc59 = [[
Di mana binatang buas yang menakjubkan muncul, Anda juga akan menemukan ahli ekstrozoologi di dekatnya. Meskipun mereka jauh lebih jarang daripada binatang yang menakjubkan, mereka sangat bersemangat dengan pekerjaan mereka. Mereka mengikuti jejak binatang yang menakjubkan sampai ke ujung dunia, mencatat ekologi dan karakteristik mereka, dan menyusun catatan-catatan ini ke dalam buku-buku sebagai warisan mereka. Mereka juga membantu binatang yang menakjubkan ketika mereka dalam bahaya.
Fia sedang dalam perjalanan untuk menjadi seorang ahli ekstrozoologi melalui usahanya sendiri yang sungguh-sungguh.]],
  str_loading_h_desc60 = "Keberadaan The Illusionist & Old Bill's Circus selalu tidak diketahui. Baru-baru ini, ada kabar bahwa mereka telah diundang ke kota pelabuhan yang terkenal, Harbour City. Pemimpin sirkus, Jeno, adalah orang yang eksentrik, dan semua bawahannya memiliki keterampilan yang unik. Dia ingin memberi warga setempat festival musim panas yang luar biasa untuk diingat.",
  str_loading_h_desc61 = "Penguasa kota Harbour City tampaknya cukup terobsesi dengan Zamrud. Apa yang bisa ada di sana? Rahasia apa yang disembunyikan? Hiruk pikuk perayaan akan segera mereda, dan arus bawah yang tidak aktif di bawah geladak akan segera melonjak...",
  str_loading_h_desc62 = "Kekacauan yang disebabkan oleh Elvis tampaknya akan berakhir setelah ia ditangkap. Namun, tak ada seorang pun yang tahu motif di balik perbuatannya. Keraguan di hati Carleen membuatnya kelam, seperti cuaca di Harbor City. Kapan kebenaran akan terungkap? Untuk menemukan jawaban yang sebenarnya, Carleen dan temannya tinggal di Harbor City untuk melakukan penyelidikan. Sementara itu, sepertinya Elvis masih belum berniat untuk menyerah.",
  str_loading_h_desc63 = "Segel kuno terguncang, membangunkan Eclipsite legendaris yang tertidur di dasar laut dalam. Perang di pantai tak lama lagi akan pecah, seiring gelombang ombak yang menyapu Harbor City. Di hadapan pertempuran yang tak terelakkan melawan Eclipsite, apakah semua orang bisa melindungi Harbor City? Akankah Elvis menemukan jalan keluar dari krisis ini?",
  str_loading_h_desc64 = "Cloudwhale menghalau Darkflow yang memenuhi udara dan membelah awan hitam yang melingkupi Harbor City. Begitu terik matahari menyinari Harbor City, keadaan berbalik ke arah yang lebih baik. Bahkan, badai yang menderu-deru juga tampak menunjukkan tanda-tanda akan berhenti.",
  str_loading_h_desc65 = [[
The Eclipsites menyerang 12 tahun yang lalu.
Setelah pertempuran neraka yang tak terhitung jumlahnya, inilah yang tersisa dari Euforia.
Luka yang tak kunjung sembuh, berangsur-angsur bernanah.]],
  str_loading_h_desc66 = [[
Kota ini dibebani dengan terlalu banyak dosa dari masa lalu.
Mereka tumbuh seperti tumor pada tubuh, dan harus diangkat untuk pulih.
Mungkin hanya dengan begitu sinar matahari akan kembali ke tempat ini.]],
  str_loading_h_desc67 = "—Beginilah diiklankan di koran. Bangunan di pinggiran Umbraton ini telah memiliki banyak pemilik selama bertahun-tahun. Baru belakangan ini menjadi milik Andersens, yang menjadikannya rumah berhantu seperti sekarang ini. Itu seharusnya dibangun oleh seorang arsitek eksentrik yang merupakan dalang di balik perancangan tangga palsu, pintu yang salah tempat, dan jendela. Semua lampu gantung dan lukisan aneh adalah desainnya sendiri.",
  str_loading_h_desc68 = "Sebuah ruang bawah tanah yang aneh terletak di bawah apa yang sekarang dikenal sebagai Rumah Hantu Andersen. Saya tahu Anda belum pernah melihatnya sendiri. Mungkin saja pemilik saat ini tidak pernah melihatnya. Pemilik rumah terakhir menginjakkan kaki di sana hanya sekali dan menjual tempat itu tak lama kemudian sebelum pindah jauh-jauh. Ada banyak rumor seputar ruang bawah tanah, tapi aku tidak percaya satu pun. Bagaimanapun, orang yang hidup tidak memiliki cara untuk mengetahui kebenaran.",
  str_loading_h_desc69 = [[
Pusat Penelitian Illumina adalah pusat sains dan teknologi dari Federasi Illumina.
Para peneliti di sini bertanggung jawab untuk menganalisis perangkat teknologi kuno dan berinovasi teknologi baru.
Namun, tidak ada akhir untuk penelitian. Apakah Anda akan menemukan informasi yang Anda cari di sini?]],
  str_loading_h_desc70 = [[
Simulator medan perang yang dibuat oleh Pusat Penelitian Illumina dapat membawa Anda ke pertempuran apa pun yang tercatat di sistemnya.
Jangan mempertanyakan keaslian adegan yang dimunculkannya untuk Anda: tentara yang putus asa, Eclipsites yang ganas, matahari yang terhalang oleh api perang .... Semua yang Anda lihat di sini benar-benar terjadi.]],
  str_loading_h_desc71 = "Angka dan sains tidak bisa dipahami dan jauh. Hal yang aneh adalah bahwa mereka mungkin tiba-tiba menampilkan emosi dan niat dengan cara yang sangat tepat di depan kita. Beberapa jarak sebenarnya bahkan lebih menakutkan setelah diukur.",
  str_loading_h_desc72 = "Tempat di mana matahari Lumopolis tidak bersinar, di luar garis pertahanan Undercities Illumina. Kota ini adalah tempat terakhir berkumpulnya Aurorian. Terlepas dari status dan perbedaan etnis mereka, penduduk di sini bergabung menjadi satu kekuatan melawan musuh untuk menjaga budaya yang tersembunyi di kota kecil ini.",
  str_loading_h_desc73 = "Ksatria dari perbatasan ini berbeda dari yang ada di Lumopolis. Mereka berguling-guling di medan perang sehingga pasir menodai sutra putih yang mereka kenakan menjadi warna yang berbeda dari Lumopolis. Mereka lebih terbiasa mengikuti ujung pedang mereka daripada berlutut di mahkota.",
  str_loading_h_desc74 = [[
Colossus yang jatuh di sini sangat besar.
Itu pernah terbang bebas dengan sayap yang bisa menutupi langit.
Tapi sekarang dia melihat ke arah Eraveil, ditakdirkan untuk tidak pernah kembali ke sana.]],
  str_loading_h_desc75 = [[
Sebuah Colossus yang dilengkapi dengan layar raksasa dan perlengkapan audio dari atas hingga bawah.
Arkeolog mengklaim bahwa saat merayakan festival mereka, Caelestite akan menerbangkan Eulogoz ke langit dan menyiarkan lagu-lagu perayaan dan gambar tarian di seluruh Eraveil.
Namun, menurut data yang tersisa, Eulogoz dan navigatornya menghilang secara misterius sekitar seratus tahun yang lalu.]],
  str_loading_h_desc76 = [[
Seekor binatang menakjubkan yang bisa hidup selamanya.
Ada sangat sedikit informasi sejarah tentang Ouroboros, dan banyak ahli ekstrozoologi memang percaya bahwa Ouroboros sebenarnya hanyalah rekayasa belaka.
Namun, Vic sangat yakin bahwa itu ada dan percaya bahwa ada hubungan yang tidak dapat dijelaskan antara dirinya dan binatang yang menakjubkan ini.]],
  str_loading_h_desc77 = [[
Seekor Ouroboros di dalam telurnya dapat menjalin mimpi sesuai keinginannya sendiri dan membuat siklus mimpi tersebut terus menerus hingga melewati masa inkubasinya yang panjang dengan selamat.
Di masa lalu, orang-orang dengan motif tersembunyi sengaja masuk ke dalam mimpi Ouroboros untuk mencoba dan menghentikannya agar tidak menetas sehingga mereka dapat mencapai kehidupan abadi dalam mimpinya, tetapi mereka semua gagal tanpa kecuali.
Itu sebabnya Anda harus berpikir dua kali sebelum memasuki mimpi Ouroboros.]],
  str_loading_h_desc78 = "Shadowind berlabuh di Twin Pavilions Bay dan membawa kabar gembira bagi penduduk asli Longzhou yang tinggal di sana. Rute pelayaran Shadowind menghubungkan Longzhou dan Astra dan telah menjadi jalur penting untuk pertukaran budaya dan perdagangan timbal balik antara kedua wilayah. Kapal-kapal ini melakukan perjalanan ke sana kemari, sarat dengan barang-barang unik, makanan lezat, dan harta karun Longzhou, dan menyediakan perjalanan pulang yang telah lama dicari bagi mereka yang terdampar jauh dari rumah.",
  str_loading_h_desc79 = "Laut tidak menyerah ketika menghadapi pasukan yang dipersiapkan dengan baik, juga tidak menunjukkan belas kasihan kepada ikan yang mengepakkan ekornya. Saat badai menyerang, Anda hanya mengalami tahun-tahun tak terbatas dari keberadaannya dalam satu saat. Saat berada di tengah-tengah badai, para pelaut sering berdoa kepada ikan ular, yang ingin mengalami nasib serupa, untuk terjun tanpa rasa takut ke kedalaman lautan dan kemudian dengan selamat pindah ke perairan dangkal di kampung halaman mereka.",
  str_loading_h_desc80 = "Kapal yang tenggelam itu tergeletak dengan tenang di dasar samudra, lebih tenang pada saat ini daripada saat-saat ketika ia mengapung di atas ombak. Laut menelan semua suara, menenggelamkan tangisan kehidupan dan hanya menyisakan bayangan akhir—sebuah foto pudar tersapu ke pantai. Laut tidak terbatas. Mungkin ada banyak kuburan kapal seperti ini, tapi tidak ada yang membayar upeti ke kuburan tersebut. Itu adalah tangisan yang dirindukan oleh dunia.",
  str_loading_h_desc81 = "Mencapai levelnya dan menilai apa yang telah dia lakukan atau tidak lakukan adalah hal yang konyol. Dia tidak perlu menjelaskan apa pun kepada siapa pun, jadi semua masalahnya adalah miliknya sendiri, dan sikapnya adalah yang terpenting. Dia tidak merasa menyesal; sebaliknya, sesuatu yang lebih tidak berperasaan—rasa bersalah. Menggunakan satu orang untuk mengimbangi dosa seratus orang... kesalahannya datang tanpa pilihannya sendiri, namun memberinya kedamaian hati nurani.",
  str_loading_h_desc82 = [[
Ketika datang untuk merayakan Hari Mahkota Bulan, ada kebiasaan yang berbeda di seluruh benua.
Di Illumina, mereka relatif rendah hati dan pragmatis. Mereka mengungkapkan cinta mereka dengan memberikan gulungan kayu manis kepada kekasih mereka.
Di Lumopolis, mereka lebih fokus pada rasa upacara, dan saling memberikan semanggi merah yang berharga untuk mewakili ketulusan mereka.
Di Northland, mereka merayakannya dengan sederhana, menghadiahkan botol kecil berisi air dari Lake Mirror sebagai kenang-kenangan, melambangkan cinta yang murni.]],
  str_loading_h_desc83 = [[
Penangkap mimpi yang ditenun dengan cermat, liontin topaz yang sangat indah, permadani yang pernah menjadi koleksi di kalangan bangsawan...
Rasanya seolah-olah Anda sedang memasuki toko barang antik yang indah alih-alih kantor Courier Union.
Segala sesuatu di sini tampaknya menunjukkan bahwa pemilik ruangan ini memiliki selera yang luar biasa.
Kebanyakan orang di Gurun Rediesel sangat hemat, tetapi Jeriah hanya menuntut yang terbaik dalam hal kualitas hidup dan standar estetika.]],
  str_loading_h_desc84 = [[
Wilayah tengah Gurun Rediesel dihiasi dengan oasis, seperti bintang di dalam galaksi pasir merah yang luas.
Perairan gurun yang berharga telah memelihara kehidupan yang tak terhitung jumlahnya, namun menimbulkan teror yang tak terbayangkan, di antaranya yang paling terkenal adalah cacing pasir.
Raksasa-raksasa ini selalu mengintai di pasir menunggu, siap menyerang apapun yang lewat.]],
  str_loading_h_desc85 = [[
Menurut kebiasaan di seluruh benua, Mooncrown Day adalah hari bagi para kekasih untuk mengungkapkan perasaan mereka, sehingga banyak orang mengadakan pernikahan pada hari ini.
Kepada bangsawan yang lebih tradisional, kurir mengantarkan kebahagiaan ke pesta pernikahan. Beberapa bahkan menghabiskan banyak uang untuk mengundang utusan ini untuk hadir.
Untuk mencegah perilaku semacam ini, yang sangat mempengaruhi efisiensi kerja kurir di benua itu, Serikat Kurir telah mempromosikan kegiatan lain dalam upaya menghapus tradisi ini secara bertahap.]],
  str_loading_h_desc86 = "Di bawah saran dari Schwartz, Balai Kehakiman telah membuka divisi sementara untuk menangani perselisihan cinta baru-baru ini pada waktu khusus tahun ini untuk memastikan keseriusan persidangan pengadilan utama. Memasuki Divisi Percintaan seperti duduk di gerbong yang rodanya tidak akan berhenti berputar. Sebelum palu hakim jatuh, pastikan Anda mengungkap bukti paling kritis.",
  str_loading_h_desc87 = "Antusiasme Mooncrown Day jelas belum surut di Lumopolis, karena sekelompok peminat Mooncrown mengadakan salon cinta dadakan. Ditandai dengan peluncuran balon udara berbentuk bulan, baik rakyat jelata maupun bangsawan berkumpul di bawah bulan untuk menari, berbaur, dan menikmati himne musim. Ini juga saat perasaan fana dan abadi dapat berkembang dalam sekejap mata.",
  str_loading_h_desc88 = "Tidak ada seorang pun di Lumopolis yang tidak mengenal Stairway to the Skies. Dengan semua orang yang lewat dan mengunjungi tempat ini, jalan yang tak terhitung jumlahnya mengarah ke Stairway to the Skies, Anda akan selalu menemukan diri Anda berjalan di salah satunya. Di kota yang sangat bertingkat ini, tangga panjang ini memiliki banyak arti di luar \"jalan\" sederhana. Saat menaiki anak tangga itu sebagai seorang anak, seseorang dapat melihat bintang-bintang; ketika mendakinya sebagai orang dewasa, seseorang bahkan dapat mencapai Taman Lumopolis.",
  str_loading_h_desc89 = "Mari kita pikirkan kembali apa arti \"keadilan\". Itu tidak memiliki definisi yang tepat. Umumnya, kebanyakan orang percaya bahwa \"keadilan\" berarti melakukan hal yang benar. Orang-orang ini memilih perwakilan untuk berbicara atas nama mereka, dan perwakilan ini memadatkan pendapat mereka menjadi suara. Sudahkah Anda menemukan hasil yang tak terelakkan dari sistem ini? Struktur masyarakat kita ditakdirkan untuk mendefinisikan \"keadilan\" dengan jumlah suara yang diberikan, jadi sekarang, saya adalah \"keadilan\".",
  str_loading_h_desc90 = [[
Atas perintah Shadowlord, Panti Asuhan Umbraton telah dibangun kembali di situs aslinya.
Sama seperti Umbraton di masa lalu, panti asuhan tua itu adalah limbah korupsi, kehilangan sedikit pun harapan.
Api meruntuhkan masa lalu, dan matahari bersinar tanpa rasa takut di atas tanah baru di bawahnya.]],
  str_loading_h_desc91 = [[
Hati dibesarkan di sini bersama ibunya.
Meskipun dia tidak diizinkan keluar, dia memiliki masa kecil yang bahagia, bermandikan cinta keibuan.
Kuda poni yang dijahit ibunya untuknya adalah satu-satunya teman bermainnya sebagai seorang anak, dan buku bergambarnya yang berwarna-warni adalah harta karun imajinasinya yang melimpah.
Tapi sekarang, semuanya hilang.]],
  str_loading_h_desc92 = [[
Undercity dulunya tidak terdaftar dan tidak disebutkan namanya, tetapi diambil alih dan dibangun kembali oleh seseorang bertahun-tahun yang lalu.
Itu kemudian berganti nama menjadi "Undercity X" dan kemudian "Institute X" setelah serangkaian fasilitas penelitian didirikan.
Sayangnya, tempat itu akhirnya dihancurkan oleh api.]],
  str_loading_h_desc93 = [[
Di bawah yurisdiksi Profesor Ulysses dari Illumina, Arsip menyimpan banyak informasi rahasia.
Bobot sejarah di balik setiap bagian tipis data tidak diketahui, membiarkan kedalaman rahasia yang sebenarnya terkubur.]],
  str_loading_h_desc94 = [[
Metode modifikasi paling efektif yang ditemukan sejauh ini adalah menggabungkan berbagai metode peningkatan yang telah terbukti berhasil pada subjek eksperimen yang sama.
Kita hanya membutuhkan pikiran yang kuat untuk menghasilkan hasil yang sukses.]],
  str_loading_h_desc95 = [[
Latihan Militer bertujuan untuk memberikan panggung bagi seluruh peserta untuk belajar, bekerja sama, dan berkompetisi.
Ada dua tahap: persiapan kursus dan penilaian akhir.
Tim pemenang akan mendapat kesempatan untuk berpartisipasi dalam pertandingan eksibisi dengan Grand Marshal of Illumina.]],
  str_loading_h_desc96 = [[
Makna kemenangan dalam pertempuran tidak perlu diragukan lagi.
Pertempuran mewujudkan ketekunan, tanggung jawab, dan kepahlawanan yang tak tergoyahkan setiap Aurorian dalam menghadapi kegelapan saat kami berusaha untuk menegakkan cahaya harapan tanpa goyah.]],
  str_loading_h_desc97 = [[
Bola kristal khusus yang dikembangkan oleh Boaz, master ramalan legendaris dari Northland.
Setelah diaktifkan dengan Lumina, secara otomatis merekam semua peristiwa yang terjadi dalam rentang tertentu dari aktivator sepanjang hari.
Aktivator hanya perlu menyuntikkannya dengan Lumina sekali lagi untuk memindahkan diri mereka sendiri atau orang yang disentuhnya ke Crystal of Eternal Memory dan meninjau kembali apa yang terjadi pada hari itu.]],
  str_loading_h_desc98 = [[
Dalam rangka memperingati Schwartz kontribusi keluarga untuk Lumopolis, masyarakat kota secara spontan memutuskan untuk mengadakan perayaan pada hari leluhur pertama dari Schwartz keluarga menjadi Tuan Kota. Seiring berjalannya waktu, hari ini menjadi hari libur resmi Lumopolis.
Itu Schwartz keluarga secara konsisten mengadakan pawai, perayaan, makan malam sosial, dan acara lainnya pada hari ini.
Namun, sejak Krisis Darkover, skala perayaan secara bertahap berkurang.]],
  str_loading_h_desc99 = "Ribuan tahun lalu, nenek moyang keluarga Kartima menandatangani kontrak dengan para naga. Selama ribuan tahun, Dragonkin yang terbangun telah menyambut naga mereka sendiri, bersumpah untuk selamanya setia satu sama lain dan tanpa syarat mengorbankan hidup dan kekuatan mereka untuk satu sama lain. Namun, untuk berbaur dengan masyarakat Aurorian, keluarga Kartima menganggap Dragonkin yang terbangun sebagai orang luar dan melarang mereka bereproduksi. Mengapa sikap mereka berubah begitu tiba-tiba masih belum terjawab. Satu-satunya hal yang dapat dipastikan adalah bahwa Mime Kartima, sang pemimpin keluarga, kembali memanggil para naga. Namun sejak hari itu, keluarga mereka mulai menurun drastis.",
  str_loading_h_desc100 = "\"Anda mungkin memiliki banyak pertanyaan di benak Anda, dan saya tidak dapat menjamin untuk mendapatkan semua jawabannya. Perjalanan ini dimaksudkan untuk singkat, jadi saya mendorong Anda untuk menghargai pengalaman singkat ini di atas segalanya.\"",
  str_loading_h_desc101 = [[
Lahir dari keluarga berpendidikan tinggi, Joshua adalah wanita luar biasa dan berpengetahuan luas yang unggul dalam bidang akademik dan pertempuran. Ayahnya adalah seorang sarjana terkenal yang mengajari Daniel ketika dia masih muda. Begitulah cara mereka bertemu dan akhirnya menjadi pasangan yang mengatasi penghalang kelas. Kisah cinta mereka adalah kisah klasik dari era baru Lumopolis, yang menginspirasi pemuda dan pemudi yang tak terhitung jumlahnya dengan kerinduan dan harapan akan masa depan. Joshua memenuhi harapan rakyat, menampilkan dirinya dengan citra sesempurna Bunda Suci, yang sangat meningkatkan kepercayaan politik rakyat terhadap Schwartz keluarga.
Begitulah keadaannya sampai kecelakaan itu.]],
  str_loading_h_desc102 = [[
Dia pernah punya nama sendiri, tapi sekarang dia dipanggil Joshua atau Anak Montague. Berbeda dengan City Lord yang berkuasa, mantan City Lord, ayah Daniel, adalah seorang tiran. Melalui tirani yang belum pernah terjadi sebelumnya, dia mengubah kelas yang telah memperkuat pandangannya di Lumopolis selama seratus tahun dan juga membersihkan lawannya dengan sangat kejam. Joshua adalah orang yang selamat dari House Montague.
Beberapa konspirator membuat argumen berdasarkan para penyintas ini untuk mendirikan organisasi dengan tujuan menjatuhkan Schwartz keluarga. Namun, itu hanyalah perjuangan politik untuk mendapatkan lebih banyak kekuasaan, dan tidak ada yang benar-benar peduli dengan kesedihan para penyintas. Kemarahan yang tak terpuaskan di mata mereka hanyalah alat di mata orang lain.]],
  str_loading_h_desc103 = "Denuo Wonderland, terletak jauh di dalam Gurun Rediesel dan dikelilingi oleh jurang yang tenang, menandai fase pertama pengembangan Denuo Valley Resort. Rediesel Wrench memainkan peran penting dalam merancang beberapa wahana saat pendirian taman, memastikan pengalaman yang mendebarkan dan menantang bagi semua pengunjung. Layak dicatat bahwa roda langit tetap buka di malam hari, memungkinkan tamu untuk menikmati pertunjukan kembang api romantis saat menaikinya.",
  str_loading_h_desc104 = [[
Terletak di sebelah negeri ajaib, Denuo Resort Hotel menampilkan diri sebagai istana megah yang anggun muncul dari negeri ajaib.
Lanskap kebun khas di pintu masuk depan mencerminkan esensi budaya Lembah Denuo dan rasa hormat yang mendalam para pengembang terhadap alam. Patut diperhatikan adalah artefak buatan tangan yang dipamerkan di lobi besar dan teras hotel, yang dibuat oleh pengrajin lokal yang menunjukkan bakat luar biasa mereka. Seluruh hotel seperti museum, menceritakan sejarah menarik Lembah Denuo dan legenda memikat Dewi Denuo untuk setiap tamu yang dihargai.]],
  str_loading_h_desc105 = [[
Lembah Denuo berdiri sebagai permata yang belum terjamah, menampilkan tata letak geografis yang menguntungkan dan pemandangan alam yang indah.
Seperti yang diceritakan legenda setempat, suatu bencana alam misterius pernah melanda ngarai ini, menghapuskan seluruh desa. Kejadian ini menjadi pengingat mendalam tentang alam, mendorong pengembang untuk mengutamakan restorasi dan pelestarian yang ramah lingkungan sepanjang proses pengembangan. Kini, Lembah Denuo berkembang sebagai suaka yang subur, menyediakan tempat perlindungan yang harmonis bagi berbagai satwa liar dan tumbuhan yang menarik.]],
  str_loading_h_desc106 = [[
Denuo Valley Resort Hotel dilengkapi dengan sistem pemurnian udara canggih. Untuk meminimalkan kebisingan yang dihasilkan selama sirkulasi udara, pemilik resor mengikuti saran staf dan membangun ruang bawah tanah untuk menampung mesin yang besar.
Sedikit yang mereka tahu, di balik pintu rahasia di ruangan itu, ada terowongan misterius dan tersembunyi. Disimpan di dalamnya adalah barang-barang yang tampaknya membawa sejarah yang jauh dan menarik.]],
  str_loading_h_desc107 = [[
Sejarah Penjara Illumina membentang sepanjang zaman, didirikan dengan tujuan awal menjaga keamanan federasi, menghukum perilaku kriminal, dan mendorong introspeksi dan reformasi di antara para pelaku.
Narapidana diklasifikasikan ke dalam berbagai kategori dan tingkatan di dalam penjara berdasarkan tingkat bahaya mereka, sifat kejahatan mereka, dan durasi hukuman mereka. Biasanya, komite secara langsung menunjuk kru manajemen penjara keamanan tinggi. Siapa pun yang memasuki fasilitas keamanan tinggi ini harus menyediakan dokumen yang valid.]],
  str_loading_h_desc108 = [[
Benteng Lumo merupakan tempat bagi para pengasing awal dari Lumopolis, termasuk ksatria, penduduk, dan keturunan mereka, yang semuanya diperintah oleh bangsawan setempat dari Lumopolis. City Lord saat ini, Dietrich, telah mengumpulkan kekayaan dalam beberapa tahun terakhir melalui penambangan bijih dan telah membentuk sebuah pasukan, yang memberinya pengaruh yang cukup besar atas kota-kota permukaan di Lumopolis.
Di dalam Benteng Lumo, terdapat gereja independen dan sektor infrastruktur, yang, pada saat perang, berkomitmen untuk melindungi penduduk Lumopolis.]],
  str_loading_h_desc109 = [[
Dilepaskan oleh Eclipsite Mudbundle, lumpur tercemar menyapu daratan seperti gelombang obsidian. Di mana pun ia menyentuh tanah, desisan korosif yang ganas meletus, diikuti oleh tanah yang runtuh dan tanaman yang layu. Bau busuk pembusukan yang kuat terus berada di udara saat rawa itu berkembang dengan cepat, menjebak makhluk tak bersalah dalam cengkeramannya.
Mudbundle mengendap di kedalaman lumpur, mampu bergerak lincah dan menyerang Aurorian. Di sisi lain, Eclipsite memanfaatkan Darkflow dalam lumpur untuk meningkatkan kemampuan serangan mereka.]],
  str_loading_h_desc110 = [[
Sejauh yang kita ketahui, Warp kemungkinan merupakan Darkflow yang kuat berasal dari Eclipse. Setiap kali tim yang terjebak di dalamnya maju sejauh tertentu, mereka selalu kembali ke titik awal. Sifat sebenarnya dari seni ini masih menjadi misteri.
'Titik awal' ini mengacu pada pusat dari ruang lingkaran tetap, yang membatasi gerakan tim di dalam radiusnya. Hal ini membuat Aurorian merasa terus berlari dalam lingkaran, terjebak bahkan dalam ilusi lingkaran tak berujung.]],
  str_loading_h_desc111 = [[
Benteng Lumo merupakan tempat bagi para pengasing awal dari Lumopolis, termasuk ksatria, penduduk, dan keturunan mereka, yang semuanya diperintah oleh bangsawan setempat dari Lumopolis. City Lord saat ini, Dietrich, telah mengumpulkan kekayaan dalam beberapa tahun terakhir melalui penambangan bijih dan telah membentuk sebuah pasukan, yang memberinya pengaruh yang cukup besar atas kota-kota permukaan di Lumopolis.
Di dalam Benteng Lumo, terdapat gereja independen dan sektor infrastruktur, yang, pada saat perang, berkomitmen untuk melindungi penduduk Lumopolis.]],
  str_loading_h_desc112 = [[
Desain sel tahanan Illumina mengikuti standar dan fasilitas yang telah ditetapkan, untuk memastikan pengawasan narapidana yang efektif dan langkah-langkah keamanan. Setiap sel menyediakan ruang penyimpanan bagi terpidana untuk mengamankan barang pribadi, mulai dari wadah kecil hingga sedang, pakaian, dan bahan bacaan. Pencahayaan dan ventilasi juga tersedia untuk kenyamanan dan keamanan di dalam sel.
Inspeksi dan pemeliharaan rutin sangat penting untuk sel tahanan, untuk memastikan pemeliharaan standar keamanan dan kebersihan yang berkelanjutan. Rumor mengatakan bahwa fasilitas ini juga menahan penjahat dari faksi lain.]],
  str_loading_h_desc113 = "Sebuah domain yang melampaui dunia entitas materi, tampaknya hanya dapat dicapai melalui jalur unik. Pemimpin True Order mengklaim telah menerima wahyu dari Tuhan Kebenaran di lokasi ini.\nDi dalam wilayah rahasia ini, perbedaan antara cahaya dan kegelapan menjadi sulit ditemukan, karena sesuatu yang berkilauan merah menyala tampaknya menggantikan medium udara biasa, menyebabkan Aurorian yang datang ke sini untuk pertama kalinya merasakan sensasi yang tak terlukiskan—suspensi tubuh, kompresi intens, dan lainnya.",
  str_loading_N33_Cname_01 = "Denuo Negeri Ajaib",
  str_loading_N33_Cname_02 = "Hotel Resort",
  str_loading_N33_Cname_03 = "Lembah Denuo",
  str_loading_N33_Cname_04 = "ruang bawah tanah",
  str_loading_N33_Ename_01 = "Sebuah negeri ajaib deluxe yang terletak jauh di dalam Gurun Rediesel.",
  str_loading_N33_Ename_02 = "Sebuah resor hotel mewah.",
  str_loading_N33_Ename_03 = "Sebuah kawasan ngarai yang belum dikembangkan di Denuo Valley Resort.",
  str_loading_N33_Ename_04 = "Sebuah ruang bawah tanah di hotel, yang berisi peralatan ventilasi dan langkah-langkah peredam suara.",
  str_loading_N33_des_01 = "Denuo Wonderland, terletak jauh di dalam Gurun Rediesel dan dikelilingi oleh jurang yang tenang, menandai tahap pertama pengembangan Denuo Valley Resort. Rediesel Wrench memainkan peran penting dalam merancang beberapa atraksi selama pendirian taman, memastikan pengalaman yang mendebarkan dan menantang bagi semua pengunjung. Sebagai bonus spesial, setelah matahari terbenam, semua tamu diundang untuk naik roda langit dan menikmati pertunjukan kembang api super romantis!",
  str_loading_N33_des_02 = "Terletak di sebelah Negeri Ajaib Denuo, Hotel Denuo Resort menampilkan diri sebagai istana megah yang anggun muncul dari negeri ajaib tersebut. Lanskap kebun khas di pintu masuk depan mencerminkan esensi budaya Lembah Denuo dan rasa hormat yang mendalam para pengembang terhadap alam. Patut dicatat adalah artefak buatan tangan yang dipamerkan di lobi besar hotel dan teras, yang dibuat oleh pengrajin lokal yang menunjukkan bakat luar biasa mereka. Secara keseluruhan, hotel ini menyerupai museum mini, yang menceritakan kisah sejarah kaya Desa Denuo dan legenda Dewi Denuo untuk setiap tamu yang terhormat.",
  str_loading_N33_des_03 = [[
Lembah Denuo berdiri sebagai permata yang belum terjamah, menampilkan tata letak geografis yang menguntungkan dan pemandangan alam yang indah.
Seperti yang diceritakan legenda setempat, suatu bencana alam misterius pernah melanda ngarai ini, menghapuskan seluruh desa. Kejadian ini menjadi pengingat mendalam tentang alam, mendorong pengembang untuk mengutamakan restorasi dan pelestarian yang ramah lingkungan sepanjang proses pengembangan. Kini, Lembah Denuo berkembang sebagai suaka yang subur, menyediakan tempat perlindungan yang harmonis bagi berbagai satwa liar dan tumbuhan yang menarik.]],
  str_loading_N33_des_04 = [[
Denuo Valley Resort Hotel dilengkapi dengan sistem pemurnian udara canggih. Untuk meminimalkan kebisingan yang dihasilkan selama sirkulasi udara, pemilik resor mengikuti saran staf dan membangun ruang bawah tanah untuk menampung mesin yang besar.
Sedikit yang mereka tahu, di balik pintu rahasia di ruangan itu, ada terowongan misterius dan tersembunyi. Disimpan di dalamnya adalah barang-barang yang tampaknya membawa sejarah yang jauh dan menarik.]],
  str_loading_h_desc10004 = [[
Eve lahir dan dibesarkan di Gurun Rediesel.
Dia tinggal di komunitas karavan bersama ayah yang kuat dan ibu yang penyayang.]],
  str_loading_h_desc10005 = [[
Eve selalu penasaran tentang nama jalan yang aneh ini... tapi tidak apa-apa.
Ada toko-toko keren dan klinik dokter di sini.
Itu saja yang penting!]],
  str_loading_h_desc10006 = [[
Dalam ingatan Eve, dia belum pernah berada di tempat lain selain area karavan dan Tail Street.
Sekarang, setelah berhasil membuka gerbang besi ke dunia luar, orang tuanya mungkin akan memberinya pelajaran serius jika mereka tahu.
Lagi pula... lihat, dunia luar memang cukup menakutkan.]],
  str_loading_h_desc10007 = [[
Pemandangan terus berganti di depan matanya, seperti dongeng yang indah namun tak nyata, tiba-tiba menunjukkan taring berapi.
Ilusi ini akan runtuh seperti gunung pada akhirnya, jadi teruslah melangkah...]],
  str_loading_h_desc20011 = [[
"Sejak kecil, Irridon memiliki keinginan mendalam untuk bekerja di dalam Hall of Justice.
Mengenai alasan spesifiknya... tampaknya bahkan Irridon sendiri kesulitan mengingatnya."]],
  str_loading_h_desc20012 = [[
Keluarga bangsawan yang memiliki kedudukan tinggi biasanya tidak mengirim anak-anak mereka ke Akademi Dawn untuk belajar; sebaliknya, mereka lebih memilih untuk menggunakan jasa tutor pribadi yang paling luar biasa.
Namun, ayah Irridon menyimpang dari kebiasaan tersebut. Dia berharap Irridon bisa belajar sejak dini bagaimana cara menonjol di antara orang banyak."]],
  str_loading_h_desc20013 = [[
"Dari rumah Irridon di Taman Lumopolis, hanya perlu beberapa belokan dan perjalanan menuruni Stairway to the Skies yang panjang untuk mencapai Halaman Lumopolis.
Dalam pandangan Irridon, Halaman itu tidak terlalu berbeda dari Taman Lumopolis.
Namun, bagi banyak teman sekelas Irridon saat masih di sekolah, mendaki tangga antara kelas Halaman dan kelas Taman seperti menjalani misi yang mustahil."]],
  str_loading_h_desc20014 = [[
"Selama tahun-tahun awal Irridon, dia jarang memiliki kesempatan untuk menjelajahi Lower Lumopolis.
Menurut ayahnya, tempat itu dipenuhi dengan bangsawan kelas rendahan dan rakyat jelata yang kasar, yang mungkin berdampak negatif pada anak tersebut."]],
  str_loading_h_desc20015 = [[
Di permukaan air yang tenang, gelombang emas melingkar terbentuk satu demi satu.
Pantulan di air secara bertahap terdistorsi oleh gelombang, hampir seperti ada dunia fantastis dan penuh warna di dalamnya.]],
  str_loading_h_desc80030001 = "Connolly lebih suka menyebut tempat itu \"tempat tinggal\" daripada \"rumah.\"",
  str_loading_h_desc80030002 = "Jalan-jalan tampaknya diliputi kabut mistis di bawah cahaya yang berkilauan dan berpijar, dengan kehidupan air dan penduduk yang mirip ikan berkeliaran di antara mereka.",
  str_loading_h_desc80030003 = "Dibandingkan dengan loteng yang suram dan dingin, tempat ini memberikan semangat dan kehangatan bagi Connolly. Bagi Connolly, akhirnya ada rasa memiliki dan tempat untuk kembali.",
  str_loading_h_desc80030004 = [[
Di sini, terdapat sebuah kota fantastis yang terletak di dasar laut yang mirip dengan negeri dongeng.
Connolly menyerap diri dalam dunia aqua ini, dan akankah ia berhasil melewati arus bawah yang bergolak dan bertemu dengan teman-teman dekat?]],
  str_loading_h_desc80040001 = "Sisi barat Twin Pavilions Bay dikelola oleh Umbraton. Area ini mirip dengan kota-kota lain di Astra dalam hal gaya arsitektur, tetapi terlihat lebih eksotis karena penambahan dekorasi Longzhou.",
  str_loading_h_desc80040002 = "Sisi timur Twin Pavilions Bay berada di bawah yurisdiksi Guild Lin, dan ada distrik Little Longzhou, yang dirancang untuk terlihat seperti Longzhou, di sebelah pelabuhan.",
  str_loading_h_desc80040003 = "Twin Pavilions Bay memiliki beberapa pelabuhan dengan sejumlah besar dermaga dan kapal. Ia menanggung tanggung jawab penting operasi pengiriman antara Astra dan Longzhou dan selalu siap menerima kapal dan kargo dari seluruh dunia.",
  str_loading_h_desc80040004 = "Dahulu kala, ada seorang pendekar pedang lemah yang dikutuk, yang mengayunkan pedang besar yang bisa mengalahkan setiap iblis dan mengalahkan setiap musuh. Pendekar pedang itu tidak tergoda oleh uang atau ketenaran dan berada dalam pencarian yang fokus untuk menemukan dan mematahkan segala jenis kutukan yang aneh. Akankah dia mampu membawa fajar miliknya sendiri setelah membunuh semua kutukan di dunia?",
  str_loading_h_desc80050001 = "Seorang pahlawan yang berani dan penuh humor yang bangkit dari kalangan sipil, pemimpin Legiun Northwind yang selalu dengan sukarela mengorbankan dirinya demi kerajaan dan rakyatnya. Tapi, apakah ada yang benar-benar mencoba memahami beban yang dia pikul, penderitaannya yang sudah berlangsung ribuan tahun?",
  str_loading_h_desc80050002 = "Sebelum tanah ini dikenal sebagai Astra, ia menjadi tempat tumbuhnya tunas-tunas peradaban Aurorian yang tersebar. Di antara mereka ada sebuah kerajaan, jejaknya telah lama terkikis menjadi debu, namun legenda-legenda tentangnya masih bertahan hingga hari ini.",
  str_loading_h_desc80050003 = "Menjulang di pusat kota, sebuah struktur megah menaungi keyakinan bersama semua orang di kerajaan. Tidak seperti Lumopolis hari ini, tempat suci ini tidak menolak pengungsi miskin seribu tahun lalu.",
  str_loading_h_desc80050004 = "Hanya prajurit sejati yang bisa melangkah ke arena, memamerkan kekuatan mereka di depan kerumunan, menerima hujan bunga dan sorak sorai...",
  str_loading_N35_Cname_01 = "Reruntuhan Bawah Tanah",
  str_loading_N35_Cname_02 = "Northland",
  str_loading_N35_Cname_03 = "Zarya",
  str_loading_N35_Ename_01 = "Reruntuhan dari era kuno.",
  str_loading_N35_Ename_02 = "Tanah Es dan Salju, Asal Usul Aurorian",
  str_loading_N35_Ename_03 = "Gadis Beku",
  str_loading_N35_des_01 = "Lokasi ini tidak ada di peta manapun dan tidak tercantum dalam buku panduan kebanyakan penjelajah. Reruntuhan ini dipenuhi dengan bahaya yang tak terhitung jumlahnya, seolah-olah menantang siapa pun yang mendekat untuk tidak melanjutkan lebih jauh. Rasanya semakin dalam Anda masuk, semakin jelas Anda bisa mendengar suara mekanis, tanpa emosi, dan cukup menakutkan untuk membuat penyusup berbalik dan lari. Jika Anda terus maju, apa yang akan Anda temukan di kedalaman itu?",
  str_loading_N35_des_02 = "Northland lahir dalam salju dan bertahan melalui embun beku. Di bawah perlindungan Queen, Aurorian telah menjaga Northland selama beberapa generasi. Sekarang, seperti di masa lalu, meskipun mereka harus mengorbankan nyawa atau menghadapi kesepian yang tak terbayangkan, mereka tidak pernah menghindar dari tanggung jawab ini. Namun, perlu diingat, meskipun Northland adalah tempat kelahiran Aurorian, bukan berarti tempat kelahiran semua peradaban.",
  str_loading_N35_des_03 = "Seratus tahun lebih lama daripada umur kebanyakan Aurorian, tetapi bagi Zarya, kesedihan dan penyesalan dari seabad yang lalu terasa seperti kemarin. Terpenjara dalam makam es yang tak kenal ampun selama seratus tahun, akhirnya dia dibebaskan. Namun, siapakah yang akan membebaskannya dari embun beku dan keraguan yang membeku dalam hatinya?",
  str_loading_N36_Cname_01 = "Umbraton",
  str_loading_N36_Cname_02 = "Pos Illumina",
  str_loading_N36_Cname_03 = "Rediesel Desert",
  str_loading_N36_Ename_01 = "\"Sebuah pusat bisnis dan intelijen.\"",
  str_loading_N36_Ename_02 = "\"Usir musuh, rangkul orang-orang yang berpikiran sama.\"",
  str_loading_N36_Ename_03 = "\"Gurun, dunia kebebasan yang sejati.\"",
  str_loading_N36_des_01 = "Terletak di bawah Kota Lumopolis, Umbraton adalah pusat perdagangan dan keuangan, tetapi juga menjadi sarang kejahatan, korupsi, dan penipuan. Namun, saat Anda berinteraksi dengan penduduk setempat, Anda akan menemukan bahwa tidak semua orang di Umbraton bermoral buruk. Ada beberapa orang baik di sini, seperti pemilik Restoran Liu dan bos dari Guild Cloudrover.",
  str_loading_N36_des_02 = "Ini adalah area penting untuk membela diri dari serangan Eclipsites. Prajurit yang ditempatkan di sini bertanggung jawab tidak hanya untuk memukul mundur serangan Eclipsite, tetapi juga melindungi Illumina dan melakukan patroli rutin di wilayah-wilayah terdekat dan jalur perdagangan. Dari waktu ke waktu, para prajurit ini mengadakan pesta perayaan. Terlepas dari asal-usul Anda, selama Anda belum pernah menyebabkan masalah sebelumnya atau telah membantu Illumina, mereka akan mengundang Anda.",
  str_loading_N36_des_03 = "Di tengah luasnya Gurun Rediesel, Anda akan menemui banyak makhluk aneh selain Eclipsite, dan mungkin saja Anda bisa melihat naga legendaris sekalipun. Namun, ketika orang menyebut Gurun Rediesel, hal pertama yang terlintas di pikiran adalah Rediesel Wrench yang dipimpin oleh Sinsa. Anggota kelompok ini sering menjelajahi gurun dengan kendaraan mereka, menjalani kehidupan yang bebas dan menyenangkan.",
  str_loading_c_h_name10001 = "Teluk Twin Pavilions",
  str_loading_c_h_name10002 = "Pelabuhan Twin Pavilions Bay",
  str_loading_e_h_name10001 = "Sebuah pelabuhan penting yang menghubungkan Astra dan Longzhou.",
  str_loading_e_h_name10002 = [[
Pelabuhan yang ramai ini tak pernah tidur, dengan kapal-kapal dagang yang merapat sepanjang waktu.
Kapal-kapal ini, yang sarat dengan beban harapan dan impian orang-orang, menghiasi pasang surut kehidupan di sini.]],
  str_loading_h_desc10001 = [[
Terletak di muara Sungai Emas, Twin Pavilions Bay dulunya hanyalah bisikan sebuah kota. Nasibnya berubah tak bisa kembali beberapa tahun lalu dengan kedatangan kapal pedagang pertama dari Longzhou, yang memulai transformasinya menjadi metropolis yang hidup.
Kota ini adalah studi kontras yang luar biasa: separuh timur, yang berada di sepanjang laut dan pelabuhan, berada di bawah pengawasan Lin Guild, dengan gaya arsitektur yang dipenuhi oleh gaya Longzhou; separuh barat, yang dikelola oleh Umbraton, menampilkan citra cermin Umbraton dalam pemandangan kotanya.]],
  str_loading_h_desc10002 = [[
Pelabuhan Twin Pavilions Bay, yang terbentuk oleh arus tak henti-hentinya kapal-kapal pedagang, memiliki jalinan jalan yang mencerminkan gaya Longzhou, penuh dengan denyut pasar.
Toko-toko kecil, yang sebagian besar menjadi tempat perlindungan bagi pelaut, menghiasi pemandangan, bercampur dengan rumah makan yang terjangkau, penginapan, dan penjual kaki lima sesekali.
Jembatan Emas, siluet yang jauh, berfungsi sebagai benang penghubung antara bagian timur dan barat kota.]],
  str_loading_N37_Cname_01 = "Persekutuan Cloudrover",
  str_loading_N37_Cname_02 = "Klinik Tanpa Nama",
  str_loading_N37_Cname_03 = "Serigala Hitam",
  str_loading_N37_Ename_01 = "Salah satu guild paling makmur dan terkenal di Umbraton",
  str_loading_N37_Ename_02 = "Klinik bawah tanah terpercaya",
  str_loading_N37_Ename_03 = "Munculnya geng dengan cepat di Umbraton",
  str_loading_N37_des_01 = "Sebuah guild yang didirikan oleh Sheol.\nDalam beberapa tahun singkat, guild ini berkembang dari toko bergerak yang tidak dikenal menjadi salah satu guild teratas di Umbraton.\nCloudrover Guild tidak mencapai prestasi itu tanpa alasan. Bagaimanapun, Anda bisa membeli apa saja yang bisa Anda bayangkan—dan bahkan lebih—di sini.\nBahkan kamu pun pernah tersesat di antara pilihan-pilihannya, bukan?",
  str_loading_N37_des_02 = [[
Sebuah klinik kecil di permukiman kumuh terpencil Umbraton yang tidak ada yang tahu kapan pertama kali dibuka.
Dokter dan asisten tidak pernah mengungkapkan nama mereka, jadi semua orang hanya menyebut mereka "Dokter Tanpa Nama" dan "Asisten Tanpa Nama."
Terlepas dari misteri tersebut, orang-orang miskin di sekitar masih mencari pengobatan dalam jumlah besar, mengingat betapa murah dan baiknya dokter itu.]],
  str_loading_N37_des_03 = [[
Di Umbraton, tak terhitung jumlah geng kecil yang terbentuk karena kebutuhan untuk melindungi diri, meskipun hanya sedikit yang tidak hanya berhasil menciptakan nama tetapi terus berkembang seperti Serigala Hitam.
Beberapa mengklaim bahwa Serigala Hitam didukung oleh sebuah guild besar tertentu untuk bertindak seberani itu, tetapi geng tersebut tidak pernah memberikan jawaban langsung atas rumor tersebut.
Mungkin, hal ini hanya karena tidak ada yang pernah menanyakan pertanyaan itu secara terbuka.]],
  str_loading_N38_Cname_01 = "Teluk Twin Pavilions",
  str_loading_N38_Cname_02 = "Bayangan",
  str_loading_N38_Ename_01 = "Pelabuhan Perdagangan Dwibenua",
  str_loading_N38_Ename_02 = "Kapal Laut Mekanis",
  str_loading_N38_des_01 = "Awalnya sebuah desa nelayan kecil di sisi timur Umbraton, kini telah berkembang menjadi pelabuhan perdagangan dengan kedatangan kapal-kapal pedagang Longzhou. Saat ini, sisi barat Twin Pavilions Bay dikelola oleh Umbraton, berbagi gaya arsitektur dengan kota-kota Astra lainnya. Sisi timur berada di bawah kendali Lin Guild, menampilkan jalan dan pelabuhan bertema timur yang mirip dengan gaya Longzhou.",
  str_loading_N38_des_02 = [[
Sebuah kapal laut canggih yang didanai dan dibangun oleh Lin Guild.
Dirancang dengan penambahan mesin Kerajaan Ye, kapal ini melampaui kapal tradisional dalam daya tahan dan kekuatan. Selain itu, kapal ini dilengkapi dengan perangkat untuk operasi penyelamatan bawah air. Kapal ini akan mengangkut navigator, Xuan Ji, dan lainnya ke laut dalam, menjelajahi wilayah yang belum terjamah.]],
  str_loading_N39_Cname_01 = "Persekutuan Cloudrover",
  str_loading_N39_Cname_02 = "Lubang",
  str_loading_N39_Cname_03 = "Guild Kontinental",
  str_loading_N39_Ename_01 = "Salah satu guild paling makmur dan terkenal di Umbraton",
  str_loading_N39_Ename_02 = "Sebuah tempat hiburan untuk para bangsawan.",
  str_loading_N39_Ename_03 = "Sebuah guild yang sedang naik daun berbasis di luar Umbraton.",
  str_loading_N39_des_01 = [[
Sebuah guild yang didirikan oleh Sheol. Dalam beberapa tahun singkat, ia berkembang dari toko bergerak tanpa nama menjadi salah satu guild terkuat di Umbraton.
Saat ini, Cloudrover Guild bahkan memiliki kapal udara besar yang mencakup perjalanan, belanja, rekreasi, dan liburan, semua dalam satu tempat!
Kemampuan Cloudrover Guild untuk pencapaian besar seperti itu bukan tanpa alasan. Bagaimanapun, setiap produk yang dapat dibayangkan (dan bahkan tidak dapat dibayangkan) dapat dibeli melalui mereka.Bahkan kamu juga pernah tersesat dalam pilihan yang begitu banyak, bukan?]],
  str_loading_N39_des_02 = [[
Di permukaan antara Umbraton dan Lumopolis terdapat sebidang tanah luas yang dulu dikenal sebagai "The Pit." Dahulu kala, tempat ini berfungsi sebagai arena olahraga berdarah bagi para bangsawan Lumopolis. 
Di sini, mereka akan melemparkan seratus penjahat tangguh ke dalam The Pit, dan memaksa mereka untuk saling membunuh demi hiburan mereka; orang terakhir yang bertahan akan menerima pengampunan penuh, serta hadiah mewah dari bangsawan yang mensponsori mereka. Seiring waktu, sejumlah pejuang muncul dari Umbraton, gladiator yang secara sukarela memasuki The Pit dalam pencarian kekayaan dan kemuliaan.
Sebelum Krisis Darkover, para bangsawan sudah mulai perlahan mundur ke keamanan Lumopolis, dan The Pit mulai meredup; namun demikian, budaya "kekuatan di atas segalanya" tetap bertahan dan menjadi status quo di Umbraton. Tak lama, gelanggang pertarungan ilegal yang berusaha meniru kejayaan The Pit bermunculan di seluruh kota, menarik perhatian yang sangat besar.]],
  str_loading_N39_des_03 = [[
Sebuah guild skala besar yang muncul di luar Umbraton. Pemimpinnya adalah seorang wanita misterius yang jarang menunjukkan wajahnya di depan umum.
Jarang sekali guild tumbuh pesat tanpa mengandalkan keuntungan geografis dan logistik Umbraton, namun Continental Guild berhasil mencapainya dengan cara yang tidak diketahui.
Seperti namanya, pengaruh Continental Guild menyebar hampir ke setiap kota kecil dan desa di tanah Astra.]],
  str_loading_c_h_name121 = "Lab Algol",
  str_loading_c_h_name122 = "Kamar Tua Illumina",
  str_loading_c_h_name123 = "Di atas Kota Gannon",
  str_loading_c_h_name124 = "Warehouse Zero",
  str_loading_c_h_name125 = "Celah yang Tidak Dikenal",
  str_loading_c_h_name126 = "Sungai Pristine",
  str_loading_e_h_name121 = "Kantor Illumina yang berteknologi tinggi dan akomodatif.",
  str_loading_e_h_name122 = "Sebuah lab lama Illumina yang penuh dengan kecurigaan dan kontroversi.",
  str_loading_e_h_name123 = "Seperti fajar, namun seperti matahari terbenam.",
  str_loading_e_h_name124 = "Sebuah gudang misterius yang tidak tercatat di Illumina.",
  str_loading_e_h_name125 = "Retakan tenggelam yang hancur dari kedalaman dan kegelapan yang tidak diketahui.",
  str_loading_e_h_name126 = "Sungai yang berkelok-kelok dan berkilauan dengan pesona yang misterius.",
  str_loading_h_desc121 = [[
Lab arsitektur campuran ini adalah kantor pribadi ilmuwan Illumina Algol. Tempat seperti ini yang menggabungkan teknologi dan kenyamanan jarang ditemukan di Gannon yang didominasi militer.
Meskipun lab ini tidak sesuai dengan Peraturan Illumina untuk Manajemen Living Quarters, tidak ada yang keberatan karena sebagian besar perabotan dibuat oleh Algol menggunakan material daur ulang. Dikatakan bahwa siapa pun yang mengunjungi lab ini bisa tidur nyenyak dengan derau elektronik di latar belakang.]],
  str_loading_h_desc122 = [[
Banyak tahun yang lalu ketika persediaan langka di Federasi Illumina, ilmuwan muda yang idealis membahas masa depan Aurorian siang dan malam di lab kecil ini.
Jika ada akhir bagi Aurorian, setiap diskusi dan pertanyaan yang diajukan adalah untuk menghentikan hal itu terjadi. Namun, meja lab, lantai, dan kerangka baja yang pernah menjadi cerminan kebijaksanaan itu sejak itu telah menghilang.]],
  str_loading_h_desc123 = [[
Ketika seseorang di Illumina menatap ke atas di Undercity, mereka tahu bahwa sinar terang yang menembus adalah hadiah dari "dunia beradab" untuk Gannon. Berkali-kali, Gannon telah bertahan dari serangan Eclipsite, sehingga orang-orang Illumina berusaha keras untuk mengusir para penyerang, dengan harapan suatu hari mereka dapat kembali ke permukaan dan menikmati sinar matahari dengan damai.
Namun, sinar ini juga merupakan perpisahan terakhir dari dunia beradab. Dengan krisis Darkover yang semakin dekat, apakah Illumina akan bertahan di rumah mereka?]],
  str_loading_h_desc124 = [[
Sebuah gudang yang luas, kosong, dan dingin dengan aroma kuat dari larutan. Ruang terbuka ini tampaknya pernah menyimpan senjata besar namun mematikan. Orang-orang yang menginjakkan kaki di dalamnya untuk pertama kalinya merasa diri mereka tidak berarti.
Mesin yang terus berjalan berfungsi sebagai jembatan antara masa lalu dan sekarang. Mendekati meja laboratorium biologi yang rumit dan berdecit, Anda hampir bisa mendengar jeritan dari banyaknya nyawa tak berdosa yang menyambut "kelahiran kembali" mereka di sini.]],
  str_loading_h_desc125 = [[
Sebuah retakan raksasa tanpa tanda-tanda kehidupan. Berdasarkan retakannya, ini adalah fenomena Zona Gelap kuno. Ledakan dahsyat di masa lalu juga tampak jelas, hanya meninggalkan lubang hitam pekat, kerikil yang melayang, dan tanah yang hangus. Di permukaan, retakan semakin menjalar ke mana-mana.
Apa yang terjadi di sini? Atau, apa yang masih terjadi?]],
  str_loading_h_desc126 = [[
Kegelapan yang tak berujung dan hening seolah waktu telah berhenti. Tiba-tiba, sebuah sungai yang misterius perlahan membentang dari "cakrawala" yang jauh seperti dalam sebuah lukisan. Ini adalah pemandangan fantasi yang belum pernah terlihat sebelumnya di peta Astra. Kemunculannya menambah misteri kenyataan dunia.
Darimana sumber sungai ini? Apakah ini nyata? Mengapa ketika Anda mengaduk air, perubahan tak terduga terjadi di suatu tempat di dunia?]],
  str_loading_c_h_name127 = "Kerajaan Ji",
  str_loading_c_h_name128 = "Krisis Pesisir di Kerajaan Ji",
  str_loading_c_h_name129 = "Festival Musim Semi",
  str_loading_e_h_name127 = "Kerajaan Perdagangan dan Pengiriman Air",
  str_loading_e_h_name128 = "Naga Maiden, Eclipsite, dan Segel",
  str_loading_e_h_name129 = "Tahun Baru Longzhou",
  str_loading_h_desc127 = "Sebuah kerajaan vasal di Longzhou bagian barat. Daerah ini dipenuhi dengan banyak sungai yang saling bersilangan, dan karena itu, memiliki sistem transportasi air yang sangat maju dengan rute kapal ke sebagian besar wilayah Longzhou, menjadikannya pusat transportasi sejak zaman kuno. Seiring berkembangnya perdagangan komersial, secara alami menjadi pusat ekonomi. Ibukotanya, Kota Haojin, sangat makmur dan menjadi tempat tinggal bagi banyak keluarga pedagang kaya, termasuk Guild Lin.",
  str_loading_h_desc128 = "Ratusan tahun yang lalu, sisa-sisa Eclipsite yang terkubur di perairan pantai Kerajaan Ji pernah merusak keluarga Dragon Maiden, seekor naga hitam berbentuk ular. Dragon Maiden harus merusaknya parah, menutup gua laut untuk mencegah meluapnya kekuatan Eclipsite. Karena kelalaian kerajaan terhadap ritual besar, segel telah dihancurkan, membebaskan Eclipsite untuk menimbulkan kekacauan. Kerajaan Ji, meskipun telah memobilisasi kekuatannya untuk merespon, telah mengalami kerugian yang cukup besar.",
  str_loading_h_desc129 = "Festival Musim Semi adalah festival paling penting di Benua Longzhou. Keluarga kerajaan akan mengadakan jamuan makan malam untuk tamu terhormat sementara warga berkumpul untuk bersantai dan berbincang. Di Kerajaan Ji, penduduk setempat mengadakan pameran kuil, memberikan penghormatan kepada Maiden Naga, dan mengusir binatang Nian selama festival, dengan harapan mendapatkan kesehatan dan keberuntungan di tahun yang akan datang. Beberapa pedagang menyewa fiendlings untuk mengadakan pertunjukan bertema ritual pengejaran binatang, menambahkan sentuhan keceriaan di awal tahun baru.",
  str_loading_c_h_name205 = "Ruang Kontrol Pesawat Illumina Federation",
  str_loading_c_h_name206 = "Perbatasan yang Tertutup Salju",
  str_loading_c_h_name207 = "Gua Perbatasan",
  str_loading_c_h_name208 = "Altar Leluhur",
  str_loading_c_h_name209 = "Benteng Kastil",
  str_loading_e_h_name205 = "Dingin dan mengesankan, dengan aroma logam yang kaya mengambang di udara.",
  str_loading_e_h_name206 = "Perbatasan barat laut Northland yang jarang dikunjungi.",
  str_loading_e_h_name207 = "Sebuah gua kuno yang terselubung lapisan es.",
  str_loading_e_h_name208 = "Tanah suci misterius yang dijaga oleh generasi suku Snow Fox.",
  str_loading_e_h_name209 = "Sebuah kastil kuno yang dilanda perang.",
  str_loading_h_desc205 = "Meski tidak sebesar Ruang Kontrol Colossus, tempat ini cukup untuk menampung tim ekspedisi berukuran sedang. Dindingnya dipenuhi dengan panel instrumen dan layar yang rumit, mencatat berbagai parameter dan data pesawat dengan akurat. Saat penunjuk pada panel instrumen terus berayun, suara mekanis ritmis yang samar tampaknya beresonansi dengan frekuensi perhitungan mekanis raksasa di dalam Illumina Undercity.",
  str_loading_h_desc206 = "Di bawah langit yang suram penuh salju, gurun bersalju yang dulunya tak terbatas tampaknya memiliki akhir. Gunung-gunung tinggi berdiri seperti dinding di kejauhan, memisahkan tempat ini dari dunia luar. Namun, Hutan Snowpine yang sepi menghadapi serangan mengerikan lainnya, dengan rumah-rumah berubah menjadi puing, pohon pinus salju tega dipatahkan, dan salju dicemari dengan bercak darah merah-hitam yang besar... Sepertinya tidak ada yang tahu atau peduli tentang makhluk yang hidup di sini.",
  str_loading_h_desc207 = "Gua yang dingin ini memiliki struktur labirin yang kompleks. Beberapa dinding es menjulang secara vertikal, sementara yang lain rendah dan sempit, memaksa orang yang lewat untuk membungkuk. Cahaya redup menyaring melalui kristal es, menciptakan bayangan bintik-bintik dan menyelimuti gua dalam bayangan putih perak yang tenang. Kolom es yang menjulang dan kasar, bersama dengan bunga es di dinding gua, berubah menjadi bentuk-bentuk aneh, siap untuk saat aurora turun.",
  str_loading_h_desc208 = "Dalam kedalaman gua gelap, sinar cahaya menembus langit-langit, jatuh ke altar di bawah, seolah-olah pencipta altar menunggu kebangkitan tiga pohon suci. Di depan altar berdiri sebuah lempengan batu yang bertuliskan runtutan kuno, menceritakan legenda \"Tiga Pohon Pinus.\" Dua patung Salju Fox yang usang berdiri menjaga, melambangkan perlindungan suku mereka terhadap altar. Para tetua pernah mengatakan bahwa meskipun tampak beku selama ribuan tahun, berkat dari pohon-pohon suci tetap bertahan.",
  str_loading_h_desc209 = "Angin kencang menyapu ke dalam kedalaman gua, meniup melalui kastil kuno yang menjulang tinggi muncul dari tanah. Di tengah badai salju yang mengamuk, interior kastil bersinar terang dengan api. Para pembela kastil bergerak, semangat mereka tinggi saat mereka maju untuk menegakkan sumpah kuno mereka. Teriakan mereka dan bentrokan senjata telah mengusir dingin dari es dan salju, membuat mereka melupakan kekerasan era ini.",
  str_loading_N45_Cname_01 = "Basis Rediesel Wrench",
  str_loading_N45_Cname_02 = "Koridor Leyline",
  str_loading_N45_Cname_03 = "Gunung Api yang Mengaum",
  str_loading_N45_Ename_01 = [[
Sebuah pangkalan sementara yang didirikan oleh Rediesel Wrench setelah mereka berhenti bergerak.
Efisien dan nyaman.]],
  str_loading_N45_Ename_02 = [[
Sebuah jalan berliku di bawah Gurun Rediesel.
Rute misterius ini terhubung dengan leylines gurun.]],
  str_loading_N45_Ename_03 = [[
Sebuah gunung berapi bawah tanah yang selalu mengaum.
Anehnya, gunung berapi ini meletus hanya 15 tahun yang lalu.]],
  str_loading_N45_des_01 = [[
